import csv,json
from pathlib import Path
from etymology_assignments import read_assignments
P=Path('curation/etymology-lab/indo-aryan-diversity-20260922');linked={r['Form_ID'] for r in read_assignments() if r['Status']=='accepted'};linked.update(r['Child_ID'] for r in csv.DictReader(open('cldf/edges.csv')) if r['Rank']=='1')
rs=[r for r in csv.DictReader(open('cldf/forms.csv')) if 'regmi-thakur2016danuwar[' in r['Source'] and r['ID'] not in linked]
groups=[('one',['ek'],'2462-2','*ekka','Turner2462 section2 explicitly places Nepali and Maithili ek under the MIA ekka replacement, not the vowel-only descendants of section1 eka. The source retained k matches that later branch; Turner’s alternative explanations of the MIA gemination remain open.'),('two',['dui'],'6648','dva','Turner6648 gives Nepali, Maithili and Bhojpuri dui two, alongside older duvi/duve forms. All five source dui responses fit this regional diphthongal continuation.'),('three',['tin'],'5994-3','trīṇi','Turner5994 section3 gives Nepali tin and Maithili tini through MIA tiṇṇi. The nasal-final source forms select trīṇi rather than the trayas/trāyas branches with preserved or differently developed r.'),('four',['cār'],'4655-2','catvāri','Turner4655 section2 explicitly gives Nepali cār and eastern cāri, via MIA *cayāri and Apabhramsha cāri. The section’s special numeral phonology is retained; the source forms are not assigned to the caur branch.'),('five',['pā̃c'],'7655','pañca','Turner7655 directly gives Nepali, Maithili and Hindi pā̃c five. The source nasal long vowel and affricate correspond to the regional reduction of pañca.'),('six',['cha','chau'],'12803-3','*kṣaṭ / *kṣvaṭ','Turner12803 section3 includes Nepali cha, Maithili chao and the addendum’s J. chau. Both source cha and chau therefore belong to this branch, distinct from section1 ṣaṣ and section2 *ṣuvaṭ.'),('seven',['sāt','sāt̺'],'13139','sapta','Turner13139 gives Nepali, Maithili and Bhojpuri sāt through MIA satta. Both unmarked and explicitly dental source t forms are preserved.'),('eight',['āt̺h'],'941','aṣṭā / aṣṭau','Turner941 gives Nepali, Maithili and Bhojpuri āṭh through MIA aṭṭha. The survey marks the stop dental in āt̺h; retain that source articulation instead of silently replacing it with Turner’s retroflex sign. This is the regional numeral family assignment.'),('nine',['nau'],'6984','nava²','Turner6984 directly gives Nepali and Maithili nau nine through MIA nava. The diphthong fits the numeral entry, not the homonymous new adjective.'),('ten',['das','d̺as'],'6227','daśa','Turner6227 gives Nepali, Bihari and Maithili das ten through MIA dasa. The source dental marking on d is retained where supplied; no aspiration or sibilant normalization is introduced.')]
a=[];lines=['# Danuwar: numerals one to ten','','Fifty proposed reflex records across ten numeral families; standing autonomous authorization.','','| # | Danuwar forms and meaning | Proposed etymology | Evidence |','|---|---|---|---|']
for i,(g,fs,parent,label,ev) in enumerate(groups,1):
 hits=[r for r in rs if r['Form'] in fs and r['Gloss']==g];assert len(hits)==5,(g,len(hits))
 for r in hits:a.append(dict(record={k:r[k] for k in ['ID','Language_ID','Form','Gloss','Source','Tags']},parent=parent,kind='reflex',citation=r['Source']+';CDIAL['+parent+' and addenda]',evidence=ev+' The five source locations and broad Danuwar language/dialect mapping uncertainty are preserved.'))
 lines.append(f'| {i} | **{" / ".join(fs)}** ‘{g}’ (5 records) | **{label}**, CDIAL **{parent}** | {ev} |')
audit={}
for line in open('data/other/forms/raw_data/census_nepal_2026/danuwar-audit.jsonl'):
 row=json.loads(line)
 for rd in row.get('readings',[]):
  ins=rd.get('installed',[])
  if len(ins)>7:audit.setdefault(ins[7],[]).extend(rd.get('review',[]))
for x in a:
 notes=audit[x['record']['Source']];assert notes and all(n.startswith('dialect mapping:') for n in notes),(x['record'],notes)
(P/'pass052-source-audit.json').write_text(json.dumps(dict(recordsChecked=len(a),onlyDialectMappingUncertainty=True,sources={x['record']['Source']:audit[x['record']['Source']] for x in a}),ensure_ascii=False,indent=2)+'\n')
(P/'pass052-decisions.json').write_text(json.dumps(dict(accepted=a,held=[]),ensure_ascii=False,indent=2)+'\n')
lines+=['','50 records and 50 reflex rows, with no additional holds in this numeral set. Every selected source audit reports dialect mapping uncertainty only; distinct source attestations are not merged.','Research: homepage danuwar-search004; full dictionary articles/addenda primary006 and separate addenda14256/14336/14480 in primary007. No new nodes or source repairs.','Validation: pending.'];(P/'pass052-review.md').write_text('\n'.join(lines)+'\n');print(len(a),'accepted')
